const automotiveKeys=["northstar-autohaus","torqueworks-garage","treadline-express","roam-motor-club"];
function isAutomotive(){return automotiveKeys.includes(state.website?.template_key);}
function automotiveProfile(){const k=state.website?.template_key;return templateInfo[k]||{brand:state.website?.name||"Automotive",eyebrow:"AUTOMOTIVE & VEHICLE SERVICES",hero:"Move with confidence.",copy:"Explore vehicle services and contact the team.",promise:[],serviceCards:[]};}
function automotivePageSpec(key){return state.pages.find(p=>p.page_key===key)?.page_spec||{};}
function automotivePageContent(key){return docFor(key)?.content||automotivePageSpec(key).content||{};}
function automotivePalette(){return {"northstar-autohaus":["#F2EEE7","#C39A55","#18212B","#FFFCF7"],"torqueworks-garage":["#EDEAE4","#D65A45","#262729","#FFFFFF"],"treadline-express":["#F5F1E8","#2867B2","#182D3F","#FFFFFF"],"roam-motor-club":["#F3EFE6","#2F7772","#173B3B","#FFFCF5"]}[state.website?.template_key]||["#F2EEE7","#C39A55","#18212B","#FFFFFF"];}
function automotiveArtSrc(id,scene){
 const [paper,accent,ink,surface]=automotivePalette(),seed=Array.from(String(id||scene||"automotive")).reduce((a,c)=>((a*33)+c.charCodeAt(0))>>>0,5381),shift=seed%150,variant=seed%4;
 let art="";
 if(/engine|diagnostic|electrical|equipment|technician/i.test(scene||""))art='<rect x="230" y="150" width="740" height="500" rx="26" fill="'+surface+'" stroke="'+ink+'" stroke-width="14"/><path d="M330 260h530m-530 120h390m-390 120h470" stroke="'+accent+'" stroke-width="28" stroke-linecap="round"/><circle cx="'+(580+shift)+'" cy="380" r="48" fill="'+accent+'"/><path d="M580 332v96m-48-48h96" stroke="'+ink+'" stroke-width="12"/>';
 else if(/tyre|wheel|alignment|balance|brake/i.test(scene||""))art='<circle cx="600" cy="380" r="240" fill="'+ink+'"/><circle cx="600" cy="380" r="160" fill="'+paper+'"/><circle cx="600" cy="380" r="80" fill="'+accent+'"/>'+Array.from({length:12},(_,i)=>{const a=i*Math.PI/6,x=600+Math.cos(a)*200,y=380+Math.sin(a)*200;return '<path d="M'+x+' '+y+'l'+(Math.cos(a)*22)+' '+(Math.sin(a)*22)+'" stroke="'+surface+'" stroke-width="16"/>';}).join("");
 else if(/rental|fleet|van|airport|pickup|city-car|premium-car/i.test(scene||""))art='<path d="M170 455l90-155q22-42 78-42h340q54 0 86 52l88 145v88H170Z" fill="'+accent+'"/><path d="M340 275h290l90 135H260Z" fill="'+surface+'"/><circle cx="340" cy="545" r="66" fill="'+ink+'"/><circle cx="740" cy="545" r="66" fill="'+ink+'"/><circle cx="340" cy="545" r="27" fill="'+paper+'"/><circle cx="740" cy="545" r="27" fill="'+paper+'"/>';
 else if(/inspection|finance|trade|calculator|warranty|guide/i.test(scene||""))art='<rect x="300" y="100" width="600" height="580" rx="30" fill="'+surface+'" stroke="'+ink+'" stroke-width="15"/><path d="M410 230h370m-370 100h280m-280 100h340" stroke="'+ink+'" stroke-width="17" opacity=".25"/><path d="M420 520l75 75 185-205" fill="none" stroke="'+accent+'" stroke-width="34" stroke-linecap="round" stroke-linejoin="round"/>';
 else if(/showroom|vehicle|sedan|suv|electric|hybrid|car|sales/i.test(scene||""))art='<path d="M135 470l95-155q24-44 84-44h370q52 0 88 54l92 145v82H135Z" fill="'+accent+'"/><path d="M330 285h315l94 140H250Z" fill="'+surface+'"/><circle cx="330" cy="555" r="72" fill="'+ink+'"/><circle cx="710" cy="555" r="72" fill="'+ink+'"/><circle cx="330" cy="555" r="30" fill="'+paper+'"/><circle cx="710" cy="555" r="30" fill="'+paper+'"/><path d="M'+(230+shift)+' 470h'+(400+variant*20)+'" stroke="'+surface+'" stroke-width="8" opacity=".7"/>';
 else art='<path d="M230 180h540l90 110-90 110H230l-90-110Z" fill="'+surface+'" stroke="'+ink+'" stroke-width="14"/><path d="M390 290h220" stroke="'+accent+'" stroke-width="36" stroke-linecap="round"/><circle cx="310" cy="500" r="75" fill="'+ink+'"/><circle cx="690" cy="500" r="75" fill="'+ink+'"/>';
 const svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 800"><rect width="1200" height="800" fill="'+paper+'"/><circle cx="'+(980-shift)+'" cy="120" r="190" fill="'+accent+'" opacity=".12"/>'+art+'<path d="M65 730H1135" stroke="'+accent+'" stroke-width="12"/><text x="68" y="95" fill="'+ink+'" font-family="Arial,sans-serif" font-size="22" letter-spacing="6">WORDPRESS STUDIO · ORIGINAL AUTOMOTIVE ART</text><text x="70" y="770" fill="'+ink+'" font-family="Arial,sans-serif" font-size="12" letter-spacing="4">'+String(scene||"AUTOMOTIVE").toUpperCase().replace(/[&<>]/g," ")+'</text></svg>';
 return "data:image/svg+xml;charset=UTF-8,"+encodeURIComponent(svg);
}
function automotiveImages(key,count=2){const rows=automotivePageSpec(key).media?.images||[];return rows.slice(0,count).map(x=>({src:automotiveArtSrc(x.id,x.scene),alt:x.alt||key.replace(/-/g," ")}));}
function automotiveHome(){
 const t=automotiveProfile(),imgs=automotiveImages("home",5),services=t.serviceCards||[],key=state.website.template_key;
 const hero='<section class="sf-auto-hero"><div class="sf-auto-hero-copy"><small>'+esc(t.eyebrow)+'</small><h1>'+esc(t.hero)+'</h1><p>'+esc(t.copy)+'</p><div class="sf-auto-actions"><a class="sf-btn" href="'+pageUrl(t.target)+'">'+esc(t.primary)+' ↗</a><a class="sf-btn secondary" href="'+pageUrl(t.secondaryTarget)+'">'+esc(t.secondary)+' ↗</a></div><div class="sf-auto-promise">'+(t.promise||[]).slice(0,3).map(x=>'<span>✓ '+esc(x)+'</span>').join("")+'</div></div><div class="sf-auto-hero-art"><img src="'+imgs[0].src+'" alt="'+esc(t.brand)+' original automotive illustration" fetchpriority="high"><span>'+esc(key==="northstar-autohaus"?"THE SHOWROOM EDIT":key==="torqueworks-garage"?"WORKSHOP / FIELD NOTES":key==="treadline-express"?"QUICK SERVICE / 01":"THE MOBILITY COLLECTION")+'</span></div></section>';
 const feature='<section class="sf-auto-feature-grid">'+services.slice(0,4).map((x,i)=>'<article><img loading="lazy" decoding="async" src="'+imgs[i+1].src+'" alt="'+esc(x[0])+' original illustration"><small>0'+(i+1)+' / '+esc(x[0])+'</small><h2>'+esc(x[0])+'</h2><p>'+esc(x[1])+'</p><a href="'+pageUrl(t.target)+'">Explore details ↗</a></article>').join("")+'</section>';
 const call='<section class="sf-auto-home-cta"><div><small>THE NEXT STEP</small><h2>'+esc(t.secondary)+'</h2><p>Vehicle details, service scope, pricing and availability are maintained by the operator. Requests are reviewed and confirmed before any commitment.</p></div><a class="sf-btn" href="'+pageUrl(t.secondaryTarget)+'">Start a request ↗</a></section>';
 return hero+feature+call;
}
function automotiveEnquiryPage(){
 const t=automotiveProfile(),content=automotivePageContent(state.page),title=content.heading||pageCopy(state.page).title||"Automotive enquiry",desc=content.description||t.copy;
 return pageHead(t.eyebrow,title,desc)+'<section class="sf-auto-enquiry"><div class="sf-auto-enquiry-copy"><small>LET’S START WITH THE DETAILS</small><h2>Tell us about the vehicle and what you need.</h2><p>Share the information you have. The team will review your request and confirm scope, pricing, vehicle availability or an appointment before you commit.</p><ul><li>Vehicle make, model and year help the team prepare</li><li>Describe the service, vehicle or rental requirement</li><li>Wait for operator confirmation of timing and terms</li></ul><p class="sf-auto-note">This form submits an enquiry only. It does not confirm a vehicle sale, repair, fitting, test drive, rental reservation or payment.</p></div><form id="sfAutomotiveEnquiry"><label>Your name<input name="name" autocomplete="name" required maxlength="120"></label><label>Email<input name="email" type="email" autocomplete="email" maxlength="180"></label><label>Phone<input name="phone" type="tel" autocomplete="tel" required maxlength="40"></label><label>What do you need?<select name="interest"><option>General information</option><option>Vehicle sales or test drive</option><option>Repair or diagnostics</option><option>Tyres or wheel service</option><option>Vehicle rental</option><option>Fleet or business enquiry</option></select></label><div class="sf-auto-vehicle-fields"><label>Vehicle make<input name="vehicle_make" maxlength="80" placeholder="e.g. Toyota"></label><label>Model<input name="vehicle_model" maxlength="80"></label><label>Year<input name="vehicle_year" inputmode="numeric" maxlength="4"></label></div><label>Preferred location or date<input name="preferred" maxlength="160" placeholder="Optional"></label><label>Message<textarea name="message" rows="4" maxlength="1200"></textarea></label><label class="sf-auto-consent"><input type="checkbox" name="consent" required><span>I agree to be contacted about this request.</span></label><button class="sf-btn" type="submit">Send request ↗</button><p id="sfAutomotiveEnquiryStatus" role="status" aria-live="polite"></p></form></section>'+automotiveMediaSection(state.page);
}
function automotiveEditorialPage(key){
 const spec=automotivePageSpec(key),content=automotivePageContent(key),title=content.heading||spec.title||pageCopy(key).title||"Automotive information",desc=content.description||"Explore operator-maintained vehicle and service information.",blocks=content.blocks||[],images=automotiveImages(key,2);
 const body=blocks.map((b,i)=>'<section class="sf-auto-content-block"><small>0'+(i+1)+' / '+esc(b.heading||"INFORMATION")+'</small><h2>'+esc(b.heading||title)+'</h2>'+(b.paragraphs||[]).map(p=>'<p>'+esc(p)+'</p>').join("")+((b.bullets||[]).length?'<ul>'+b.bullets.map(x=>'<li>'+esc(x)+'</li>').join("")+'</ul>':"")+'</section>').join("");
 const gallery='<section class="sf-auto-page-media"><div><small>THE DETAILS</small><h2>'+esc(title)+'</h2><p>Original first-party automotive illustration created for this page.</p></div><div>'+images.map(im=>'<img loading="lazy" decoding="async" src="'+esc(im.src)+'" alt="'+esc(im.alt)+'">').join("")+'</div></section>';
 const target=key.includes("test-drive")?"request-test-drive":key.includes("repair")||key.includes("estimate")||key.includes("inspection")?"estimate-request":key.includes("tyre")||key.includes("service")?"service-booking":key.includes("fleet")?"fleet-quote":"contact";
 return pageHead(automotiveProfile().eyebrow,title,desc,'<a class="sf-btn" href="'+pageUrl(target)+'">Ask the team ↗</a>')+'<section class="sf-auto-editorial"><div>'+(body||'<p>'+esc(desc)+'</p>')+'</div><aside><small>YOUR NEXT STEP</small><h2>Clear details. A considered response.</h2><p>Ask the operator to confirm specifications, price, service scope and availability.</p><a class="sf-btn" href="'+pageUrl(target)+'">Send an enquiry ↗</a></aside></section>'+gallery;
}
function automotiveMediaSection(key){const imgs=automotiveImages(key,2),title=pageCopy(key).title||key.replace(/-/g," ");return '<section class="sf-auto-page-media"><div><small>THE DETAILS</small><h2>'+esc(title)+'</h2><p>Original first-party automotive illustration created for this page.</p></div><div>'+imgs.map(im=>'<img loading="lazy" decoding="async" src="'+esc(im.src)+'" alt="'+esc(im.alt)+'">').join("")+'</div></section>';}
function automotivePage(){if(state.page==="home")return automotiveHome();if(["test-drive","request-test-drive","vehicle-enquiry","finance-enquiry","service-estimate","request-repair","book-inspection","estimate-request","service-booking","quote-request","rental-enquiry","request-vehicle","fleet-quote","contact"].includes(state.page))return automotiveEnquiryPage();return automotiveEditorialPage(state.page);}
async function submitAutomotiveEnquiry(e){
 e.preventDefault();const form=e.currentTarget,data=new FormData(form),status=root.querySelector("#sfAutomotiveEnquiryStatus"),button=form.querySelector('button[type="submit"]');
 if(preview||state.website.settings?.showcase_mode||state.website.status!=="published"){status.textContent="This is a private template preview. No request was sent.";return;}
 const name=String(data.get("name")||"").trim(),phone=String(data.get("phone")||"").trim();if(!name||!phone||!data.get("consent")){status.textContent="Enter your name and phone number and accept the contact consent.";return;}
 button.disabled=true;button.textContent="Sending request…";
 try{const interest=String(data.get("interest")||"General information"),make=String(data.get("vehicle_make")||"").trim(),model=String(data.get("vehicle_model")||"").trim(),year=String(data.get("vehicle_year")||"").trim(),preferred=String(data.get("preferred")||"").trim(),message=String(data.get("message")||"").trim(),business={company_name:"Automotive enquiry — "+(state.website.brand?.name||state.website.name),contact_name:name,phone,email:String(data.get("email")||"").trim(),business_type:"automotive-services-enquiry"},items=[{request_type:"automotive-services-enquiry",interest,vehicle_make:make,vehicle_model:model,vehicle_year:year,page:state.page,template_key:state.website.template_key}],notes=("Automotive enquiry. Interest: "+interest+". Vehicle: "+[make,model,year].filter(Boolean).join(" ")+". Preferred location/date: "+preferred+". Message: "+message).slice(0,2000),result=await storefrontApi().submitQuoteRequest(siteSlug,business,items,notes);status.textContent=(result?.message||"Your request has been received.")+" Reference: "+(result?.quote_number||"saved")+". The operator will review and confirm the next step.";form.reset();}
 catch(err){status.textContent=err.message||"Your request could not be sent. Please try again or contact the operator.";}
 finally{button.disabled=false;button.textContent="Send request ↗";}
}
function automotiveNav(){const k=state.website.template_key;return k==="northstar-autohaus"?[["home","Home"],["inventory","Inventory"],["pre-owned","Pre-owned"],["finance-options","Finance"],["aftersales","Aftercare"],["contact","Contact"]]:k==="torqueworks-garage"?[["home","Home"],["services","Services"],["diagnostics","Diagnostics"],["maintenance-plans","Maintenance"],["estimate-request","Estimate"],["contact","Contact"]]:k==="treadline-express"?[["home","Home"],["tyres","Tyres"],["wheel-alignment","Wheel service"],["service-packages","Packages"],["service-booking","Request"],["contact","Contact"]]:[["home","Home"],["fleet","Fleet"],["rental-rates","Rates"],["corporate-fleet","Business"],["rental-enquiry","Enquire"],["contact","Contact"]];}
function automotiveFooter(){const t=automotiveProfile(),brand=state.website.brand?.name||t.brand;return '<footer class="sf-footer sf-auto-footer"><div class="sf-footer-inner"><div><h3>'+esc(brand)+'</h3><p>'+esc(t.copy)+'</p></div><div><h4>Explore</h4><div class="sf-footer-links">'+automotiveNav().slice(1,4).map(([k,l])=>'<a href="'+pageUrl(k)+'">'+esc(l)+'</a>').join("")+'</div></div><div><h4>Get started</h4><div class="sf-footer-links"><a href="'+pageUrl(t.secondaryTarget)+'">'+esc(t.secondary)+'</a><a href="'+pageUrl("contact")+'">Contact</a></div></div><div><h4>Information</h4><div class="sf-footer-links"><a href="'+pageUrl("privacy")+'">Privacy</a><a href="'+pageUrl("terms")+'">Terms</a><a href="'+pageUrl("accessibility")+'">Accessibility</a></div></div></div><div class="sf-footer-bottom">© '+new Date().getFullYear()+' '+esc(brand)+'. Illustrative content; all vehicle, service, pricing and policy details must be verified by the operator before publication.</div></footer>';}

admin/commerce.css:
:root{--oc-ink:#2b2938;--oc-muted:#777483;--oc-paper:#f6f4ee;--oc-surface:#fffdf8;--oc-line:#e8e2d7;--oc-accent:#b87643;--oc-accent-dark:#945d34;--oc-green:#476c54;--oc-red:#a54a42;--oc-blue:#4a6881}
*{box-sizing:border-box}.oc-page{max-width:1800px;margin:0 auto;padding:22px clamp(14px,2.2vw,32px) 40px;color:var(--oc-ink);font-family:"DM Sans",Manrope,sans-serif}
.oc-header{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:8px 0 20px;border-bottom:1px solid var(--oc-line)}
.oc-brand{display:flex;gap:14px;align-items:flex-start}.oc-back{width:38px;height:38px;display:grid;place-items:center;border:1px solid var(--oc-line);border-radius:11px;background:var(--oc-surface);color:var(--oc-ink);text-decoration:none;font-size:19px}
.oc-eyebrow{display:block;color:var(--oc-accent);font-size:9px;font-weight:900;letter-spacing:.16em}.oc-brand h1{margin:3px 0 3px;font-family:"Playfair Display",serif;font-size:clamp(25px,3vw,36px);font-weight:700;letter-spacing:-.03em}.oc-brand p{margin:0;color:var(--oc-muted);font-size:12px}
.oc-header-actions{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.oc-store-filter{display:flex;align-items:center;gap:8px;color:var(--oc-muted);font-size:10px;font-weight:800}.oc-store-filter select{min-width:180px}
.oc-connection{display:inline-flex;align-items:center;gap:7px;padding:8px 10px;border:1px solid var(--oc-line);border-radius:999px;background:var(--oc-surface);color:var(--oc-green);font-size:10px;font-weight:800}.oc-connection:before{content:"";width:7px;height:7px;border-radius:50%;background:#5f9870}
.oc-btn{display:inline-flex;align-items:center;justify-content:center;min-height:36px;padding:8px 13px;border:1px solid #c17c48;border-radius:9px;background:var(--oc-accent);color:#fffaf4;text-decoration:none;font-size:11px;font-weight:850;cursor:pointer}.oc-btn:hover{background:var(--oc-accent-dark)}.oc-btn.secondary{background:var(--oc-surface);border-color:var(--oc-line);color:#5d5360}.oc-btn.secondary:hover{background:#f4efe6}.oc-btn:disabled{opacity:.5;cursor:not-allowed}
.oc-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:18px;padding-top:18px;align-items:start}.oc-sidebar{position:sticky;top:14px;padding:13px 10px;border:1px solid var(--oc-line);border-radius:15px;background:var(--oc-surface);box-shadow:0 6px 24px rgba(55,43,30,.035)}
.oc-sidebar-label{padding:4px 10px 11px;color:#9a8b7e;font-size:9px;font-weight:900;letter-spacing:.14em}.oc-sidebar nav{display:grid;gap:3px}.oc-sidebar nav button{display:flex;align-items:center;gap:10px;min-height:38px;padding:8px 10px;border:0;border-radius:9px;background:transparent;color:#665f6d;text-align:left;font:700 11px "DM Sans",sans-serif;cursor:pointer}.oc-sidebar nav button span{width:20px;color:#9a785f;font-size:16px;text-align:center}.oc-sidebar nav button:hover{background:#f6f1e8}.oc-sidebar nav button.is-active{background:#f1e6d9;color:#754b2e}.oc-sidebar nav button.is-active span{color:#a36135}
.oc-sidebar-foot{display:flex;align-items:center;gap:9px;margin:14px 2px 0;padding:12px 7px 4px;border-top:1px solid var(--oc-line)}.oc-health-dot{width:8px;height:8px;border-radius:50%;background:#6f9c78}.oc-sidebar-foot strong,.oc-sidebar-foot small{display:block}.oc-sidebar-foot strong{font-size:10px}.oc-sidebar-foot small{margin-top:2px;color:var(--oc-muted);font-size:9px}
.oc-workspace{min-width:0}.oc-notice{display:none;margin:0 0 12px;padding:10px 13px;border:1px solid var(--oc-line);border-radius:9px;background:#fff9ef;color:#725a43;font-size:11px}.oc-notice.is-visible{display:block}.oc-notice.success{border-color:#d9e6d8;background:#f3f8f2;color:#416a4c}.oc-notice.error{border-color:#eed4cf;background:#fff5f2;color:#914c42}
.oc-main{min-width:0}.oc-page-head{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;margin:0 0 17px}.oc-page-head h2{margin:2px 0 4px;font-family:"Playfair Display",serif;font-size:25px;letter-spacing:-.02em}.oc-page-head p{margin:0;color:var(--oc-muted);font-size:11px;line-height:1.6}.oc-kicker{color:var(--oc-accent);font-size:9px;font-weight:900;letter-spacing:.14em}
.oc-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;margin:0 0 15px}.oc-stat{padding:15px 16px;border:1px solid var(--oc-line);border-radius:12px;background:var(--oc-surface)}.oc-stat small{display:block;color:var(--oc-muted);font-size:10px;font-weight:750}.oc-stat strong{display:block;margin:7px 0 3px;font-size:24px;letter-spacing:-.04em;font-variant-numeric:tabular-nums}.oc-stat span{font-size:9px;color:var(--oc-muted)}.oc-stat .positive{color:var(--oc-green)}.oc-stat .warning{color:var(--oc-red)}
.oc-grid-2{display:grid;grid-template-columns:1.25fr .75fr;gap:13px}.oc-grid-equal{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.oc-panel{min-width:0;padding:15px;border:1px solid var(--oc-line);border-radius:13px;background:var(--oc-surface);box-shadow:0 5px 18px rgba(55,43,30,.025)}.oc-panel+.oc-panel{margin-top:13px}.oc-panel-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:0 0 12px}.oc-panel-head h3{margin:0;font-size:13px}.oc-panel-head p{margin:3px 0 0;color:var(--oc-muted);font-size:10px}
.oc-store-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.oc-store-card{padding:12px;border:1px solid var(--oc-line);border-radius:10px;background:#fff}.oc-store-card strong{display:block;font-size:12px}.oc-store-card small{display:block;margin-top:4px;color:var(--oc-muted);font-size:9px}.oc-store-card .oc-store-meta{display:flex;justify-content:space-between;gap:8px;margin-top:10px;font-size:10px}
.oc-table-wrap{width:100%;overflow:auto;border:1px solid var(--oc-line);border-radius:10px}.oc-table{width:100%;border-collapse:collapse;min-width:720px}.oc-table th,.oc-table td{padding:10px 11px;border-bottom:1px solid var(--oc-line);text-align:left;vertical-align:middle;font-size:10px}.oc-table th{background:#f8f5ef;color:#766e79;font-size:9px;font-weight:900;letter-spacing:.06em;text-transform:uppercase;white-space:nowrap}.oc-table td{color:#4b4754}.oc-table tr:last-child td{border-bottom:0}.oc-table td strong{display:block;color:var(--oc-ink);font-size:10px}.oc-table td small{display:block;margin-top:3px;color:var(--oc-muted);font-size:9px}.oc-table .oc-num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
