}
::selection{background:rgba(79,124,255,.38);color:#fff}
a{color:#9CB7FF}
a:hover{color:#C8D6FF}
button,input,select,textarea{font-family:inherit}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{
 outline:2px solid #7CA0FF;outline-offset:3px
}
.admin-app{background:transparent;grid-template-columns:258px minmax(0,1fr)}
.admin-sidebar{
 background:linear-gradient(180deg,#080E1B 0%,#0B1424 100%);
 border-right:1px solid #223149;
 color:#E6EDF8;padding:24px 15px;
 box-shadow:12px 0 36px rgba(0,0,0,.12);
}
.admin-brand{border-bottom-color:#24344D;padding:2px 10px 20px}
.admin-brand img{background:#F7F9FC;border:1px solid #E2E8F0;border-radius:12px}
.admin-brand strong{font-size:16px;font-weight:760;letter-spacing:-.035em}
.admin-brand small{color:#899AB3;font-size:11px;letter-spacing:.035em}
.admin-nav-group{gap:5px}
.admin-nav-label{color:#70829C;font-size:10px;letter-spacing:.16em;padding:0 13px 8px}
.admin-nav-link{
