}
.hf-status-partially-received,.hf-status-partially-shipped,.hf-status-partially-refunded,
.hf-status-awaiting,.hf-status-on-hold,.hf-status-hold,.hf-status-low-stock,.hf-status-limited-stock,
.hf-status-requested,.hf-status-to-do,.hf-status-todo{
