  box-shadow:0 5px 13px rgba(72,31,31,.2),inset 0 1px 0 rgba(255,255,255,.9) !important;
}
.admin-sidebar .admin-nav-child-link{
  box-shadow:0 3px 9px rgba(72,31,31,.13),inset 0 1px 0 #FFFFFF !important;
}
.admin-sidebar .admin-nav-parent-item > .admin-nav-children{
  border-color:rgba(255,238,205,.3) !important;
