admin/website-builder.css:
/* Universal Website Builder — isolated editor foundation */
.hf-builder-page{min-width:0;max-width:none}
.hf-builder-topbar{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:4px 0 16px;border-bottom:1px solid var(--border,#dce1e8)}
.hf-builder-brand{display:flex;align-items:center;gap:12px;min-width:0}
.hf-builder-back{display:grid;place-items:center;width:38px;height:38px;flex:0 0 38px;border:1px solid var(--border,#dce1e8);border-radius:11px;background:var(--card-bg,#fff);color:var(--text,#344054);font-size:20px;text-decoration:none}
.hf-builder-brand .page-eyebrow{margin:0 0 3px;font-size:9px;letter-spacing:.15em;font-weight:800;color:var(--muted,#687386)}
.hf-builder-brand h1{display:flex;align-items:center;gap:9px;margin:0;font-size:clamp(18px,2vw,25px);letter-spacing:-.04em;color:var(--text,#263247)}
.hf-builder-lab{padding:4px 7px;border-radius:5px;background:#e8edf6;color:#53617c;font-size:8px;letter-spacing:.12em}
.hf-builder-top-actions{display:flex;align-items:center;justify-content:flex-end;gap:7px;flex-wrap:wrap}
.hf-builder-btn{min-height:35px;padding:7px 11px;border:1px solid var(--border,#dce1e8);border-radius:8px;background:var(--card-bg,#fff);color:var(--text,#344054);font:600 11px/1.2 Inter,system-ui,sans-serif;cursor:pointer}
.hf-builder-btn:disabled{opacity:.38;cursor:not-allowed}
.hf-builder-btn-primary{border-color:#34466d;background:#34466d;color:#fff}
.hf-builder-save-state{display:inline-flex;align-items:center;gap:7px;margin-right:5px;color:#65728a;font-size:10px;font-weight:700}
.hf-builder-save-state i,.hf-builder-footer i{width:7px;height:7px;border-radius:50%;background:#c18b46;box-shadow:0 0 0 3px rgba(193,139,70,.13)}
.hf-builder-workspace{display:grid;grid-template-columns:238px minmax(340px,1fr) 286px;min-height:calc(100vh - 245px);margin-top:15px;border:1px solid var(--border,#dce1e8);border-radius:13px;overflow:hidden;background:#f4f6f9;box-shadow:0 8px 24px rgba(24,34,48,.055)}
.hf-builder-left,.hf-builder-right{min-width:0;background:var(--card-bg,#fff)}
.hf-builder-left{border-right:1px solid var(--border,#dce1e8)}
.hf-builder-right{border-left:1px solid var(--border,#dce1e8);display:flex;flex-direction:column}
.hf-builder-panel-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:17px 15px 12px}
.hf-builder-kicker{display:block;margin-bottom:4px;color:#8b95a6;font-size:8px;font-weight:800;letter-spacing:.16em}
.hf-builder-panel-head h2{margin:0;color:var(--text,#263247);font-size:15px;letter-spacing:-.02em}
.hf-builder-count,.hf-builder-selected-tag{display:inline-grid;place-items:center;min-width:24px;height:22px;padding:0 6px;border-radius:6px;background:#eef1f6;color:#64718a;font-size:9px;font-weight:800}
.hf-builder-tabs{display:grid;grid-template-columns:1fr 1fr;gap:3px;margin:0 12px 12px;padding:3px;border-radius:8px;background:#f0f2f6}
.hf-builder-tabs button{min-height:30px;border:0;border-radius:6px;background:transparent;color:#7c8798;font:700 10px Inter,system-ui,sans-serif;cursor:pointer}
.hf-builder-tabs button.is-active{background:#fff;color:#35486d;box-shadow:0 1px 4px rgba(20,30,45,.09)}
.hf-builder-tab-panel{padding:0 12px 15px}
.hf-builder-panel-note{margin:0 2px 12px;color:#7a8494;font-size:10px;line-height:1.55}
.hf-builder-component-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}
.hf-builder-component-grid button{display:flex;flex-direction:column;align-items:flex-start;gap:3px;min-height:88px;padding:10px;border:1px solid #e4e8ef;border-radius:9px;background:#fff;color:#34415a;text-align:left;cursor:pointer;transition:border-color .15s,transform .15s,box-shadow .15s}
.hf-builder-component-grid button:hover{transform:translateY(-1px);border-color:#aebbd0;box-shadow:0 4px 12px rgba(38,54,82,.08)}
.hf-builder-component-icon{display:grid;place-items:center;width:26px;height:26px;margin-bottom:3px;border-radius:7px;background:#edf1f7;color:#45577a;font-size:16px;font-weight:800}
.hf-builder-component-grid strong{font-size:10px}
.hf-builder-component-grid small{color:#8a94a4;font-size:8px}
.hf-builder-safe-note{display:flex;flex-direction:column;gap:4px;margin-top:16px;padding:11px;border:1px solid #e4e9f1;border-radius:9px;background:#f7f9fc}
.hf-builder-safe-note strong{color:#465675;font-size:9px}
.hf-builder-safe-note span{color:#7f8998;font-size:9px;line-height:1.5}
.hf-builder-layers{display:flex;flex-direction:column;gap:3px}
.hf-builder-layer{display:flex;align-items:center;gap:8px;width:100%;min-height:33px;padding:6px 8px;border:1px solid transparent;border-radius:7px;background:transparent;color:#5b6679;text-align:left;font:600 10px Inter,system-ui,sans-serif;cursor:pointer}
.hf-builder-layer:hover{background:#f3f5f8}
.hf-builder-layer.is-selected{border-color:#d5ddeb;background:#edf2f9;color:#34476e}
.hf-builder-layer .layer-glyph{width:18px;text-align:center;color:#8793a8}
.hf-builder-layer .layer-depth{margin-left:auto;color:#a0a8b5;font-size:8px}
.hf-builder-center{display:flex;flex-direction:column;min-width:0;background:#eef1f5}
.hf-builder-canvas-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:58px;padding:10px 15px;border-bottom:1px solid #dfe4eb;background:#fff}
.hf-builder-canvas-toolbar>div:first-child{min-width:0}
.hf-builder-canvas-toolbar strong{display:block;overflow:hidden;color:#3b4659;font-size:11px;text-overflow:ellipsis;white-space:nowrap}
.hf-builder-device-switch{display:flex;gap:3px;padding:3px;border:1px solid #e2e6ed;border-radius:8px;background:#f4f6f8}
.hf-builder-device-switch button{display:flex;align-items:center;gap:5px;min-height:29px;padding:5px 8px;border:0;border-radius:6px;background:transparent;color:#7a8596;font:700 9px Inter,system-ui,sans-serif;cursor:pointer}
.hf-builder-device-switch button.is-active{background:#fff;color:#34486e;box-shadow:0 1px 4px rgba(20,30,45,.1)}
.hf-builder-canvas-scroll{display:flex;justify-content:center;align-items:flex-start;min-height:480px;flex:1;padding:20px 14px;overflow:auto}
.hf-builder-canvas-frame{width:100%;min-height:560px;max-width:1200px;background:#fff;box-shadow:0 8px 24px rgba(30,42,60,.11);transition:width .2s ease}
.hf-builder-canvas-frame.is-tablet{width:768px;min-width:768px}
.hf-builder-canvas-frame.is-mobile{width:390px;min-width:390px}
.hf-builder-canvas{min-height:560px;background:#fff;color:#202b3c;font-family:Inter,system-ui,sans-serif}
.hf-builder-node{position:relative;outline:1px solid transparent;outline-offset:-2px;cursor:pointer}
.hf-builder-node:hover{outline:1px dashed #91a2c0;outline-offset:-2px}
.hf-builder-node.is-selected{outline:2px solid #526d9e;outline-offset:-2px}
.hf-builder-node[data-kind="section"]{min-height:110px}
.hf-builder-node[data-kind="container"]{margin-inline:auto}
.hf-builder-node[data-kind="heading"]{font-weight:800;line-height:1.08;letter-spacing:-.045em}
.hf-builder-node[data-kind="paragraph"]{line-height:1.65}
.hf-builder-node[data-kind="image"]{display:block;max-width:100%;overflow:hidden}
.hf-builder-node[data-kind="image"] img{display:block;width:100%;height:100%;object-fit:cover}
.hf-builder-node[data-kind="button"]{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:8px;background:#35486d;color:#fff;font-weight:700;text-decoration:none}
.hf-builder-node[data-kind="card"]{border:1px solid #e7eaf0;border-radius:12px;background:#fff;box-shadow:0 8px 22px rgba(30,42,60,.06)}
.hf-builder-node[data-kind="cardGrid"]{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.hf-builder-placeholder{display:grid;place-items:center;min-height:100%;padding:24px;background:linear-gradient(135deg,#e9edf3,#dbe2ec);color:#65738a;text-align:center;font-size:11px}
.hf-builder-canvas-foot{display:flex;justify-content:space-between;gap:10px;padding:9px 14px;border-top:1px solid #dfe4eb;background:#fff;color:#8490a0;font-size:9px}
.hf-builder-inspector{flex:1;min-height:0;padding:0 14px 16px;overflow:auto}
.hf-builder-inspector-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:260px;padding:20px;text-align:center}
.hf-builder-inspector-empty>span{display:grid;place-items:center;width:38px;height:38px;margin-bottom:10px;border-radius:12px;background:#eef2f8;color:#61769c;font-size:20px}
.hf-builder-inspector-empty strong{color:#46536a;font-size:11px}
.hf-builder-inspector-empty p{max-width:190px;color:#8993a2;font-size:9px;line-height:1.6}
.hf-builder-field{display:flex;flex-direction:column;gap:5px;margin:0 0 13px}
.hf-builder-field>span,.hf-builder-field label{color:#68758a;font-size:9px;font-weight:750}
.hf-builder-field input,.hf-builder-field select,.hf-builder-field textarea{box-sizing:border-box;width:100%;min-height:34px;padding:8px 9px;border:1px solid #dfe4eb;border-radius:7px;background:#fff;color:#344054;font:10px Inter,system-ui,sans-serif;outline:none}
.hf-builder-field textarea{min-height:72px;resize:vertical;line-height:1.5}
.hf-builder-field input:focus,.hf-builder-field select:focus,.hf-builder-field textarea:focus{border-color:#8195ba;box-shadow:0 0 0 3px rgba(96,121,166,.12)}
.hf-builder-field input[type="color"]{height:36px;padding:3px}
.hf-builder-field-row{display:grid;grid-template-columns:1fr 1fr;gap:9px}
.hf-builder-inspector-section{margin:0 0 16px;padding-bottom:13px;border-bottom:1px solid #edf0f4}
.hf-builder-inspector-section h3{margin:0 0 11px;color:#46536a;font-size:9px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}
.hf-builder-right-foot{display:flex;flex-direction:column;gap:4px;padding:11px 14px;border-top:1px solid #e8ebf0;color:#8993a2;font-size:8px}
.hf-builder-footer{display:flex;justify-content:space-between;gap:12px;padding:11px 2px;color:#8690a0;font-size:9px}
.hf-builder-footer span:first-child{display:flex;align-items:center;gap:7px;color:#69758a;font-weight:750}
.hf-builder-footer i{background:#7b9a83;box-shadow:0 0 0 3px rgba(123,154,131,.12)}
.hf-builder-empty-layer{padding:12px;color:#8a94a4;font-size:9px}
@media(max-width:1180px){.hf-builder-workspace{grid-template-columns:205px minmax(300px,1fr) 260px}}
@media(max-width:900px){.hf-builder-workspace{grid-template-columns:190px minmax(280px,1fr);min-height:calc(100vh - 230px)}.hf-builder-right{grid-column:1/-1;border-top:1px solid var(--border,#dce1e8);border-left:0}.hf-builder-inspector{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.hf-builder-inspector-section{margin:0}.hf-builder-right-foot{flex-direction:row;justify-content:space-between}}
@media(max-width:620px){.hf-builder-topbar{align-items:flex-start;flex-direction:column}.hf-builder-top-actions{justify-content:flex-start}.hf-builder-workspace{display:flex;flex-direction:column}.hf-builder-left{border-right:0;border-bottom:1px solid var(--border,#dce1e8)}.hf-builder-component-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.hf-builder-component-grid button{min-height:76px;padding:8px}.hf-builder-canvas-toolbar{align-items:flex-start;flex-direction:column}.hf-builder-device-switch{width:100%}.hf-builder-device-switch button{flex:1;justify-content:center}.hf-builder-canvas-scroll{justify-content:flex-start;min-height:420px;padding:12px 8px}.hf-builder-canvas-frame{min-height:520px}.hf-builder-inspector{display:block}.hf-builder-footer{flex-direction:column;gap:5px}}
@media(prefers-reduced-motion:reduce){.hf-builder-component-grid button,.hf-builder-canvas-frame{transition:none}}

/* Shared WordPress preview/editor navigation */
.hf-builder-sections{margin-top:14px;margin-bottom:10px}
.hf-builder-security-strip{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin:10px 0 13px;padding:10px 12px;border:1px solid #e3e7ed;border-radius:9px;background:#f8f9fb;color:#69758a;font-size:9px;line-height:1.5}
.hf-builder-security-strip strong{color:#43516a;font-size:10px}
.hf-builder-security-strip span{padding-left:9px;border-left:1px solid #d9dfe8}
@media(max-width:620px){.hf-builder-security-strip{align-items:flex-start;flex-direction:column;gap:5px}.hf-builder-security-strip span{padding:0;border:0}}

#builderSendPreview{min-height:36px}
